<?php
namespace App\RecipeProduction\Http\Controllers;
use App\Http\Controllers\Controller;
use App\Models\Product;
use App\RecipeProduction\Models\{MaterialCategory,ProductionOrder,RawMaterial,Recipe};
use App\RecipeProduction\Services\RecipeProductionService;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;

class RecipeProductionController extends Controller
{
 public function __construct(private RecipeProductionService $service) {}
 public function dashboard(){return response()->json(['data'=>['materials'=>RawMaterial::count(),'recipes'=>Recipe::count(),'orders'=>ProductionOrder::count(),'completed_orders'=>ProductionOrder::where('status','completed')->count(),'total_cost'=>ProductionOrder::sum('actual_cost'),'low_stock'=>RawMaterial::whereColumn('available_quantity','<=','minimum_stock_alert')->count()]]);}
 public function categories(Request $r){$q=MaterialCategory::query()->withCount('materials')->when($r->search,fn($q,$v)=>$q->where('name','like',"%$v%")); return response()->json(['data'=>$q->latest()->paginate($r->integer('per_page',20))]);}
 public function categoryStore(Request $r){$data=$r->validate(['name'=>'required|string|max:255','code'=>'required|string|max:40','description'=>'nullable|string','active'=>'boolean']); return response()->json(['data'=>MaterialCategory::create($data)],201);}
 public function categoryUpdate(Request $r,MaterialCategory $category){$category->update($r->validate(['name'=>'required|string|max:255','code'=>'required|string|max:40','description'=>'nullable|string','active'=>'boolean'])); return response()->json(['data'=>$category]);}
 public function categoryDestroy(MaterialCategory $category){if($category->materials()->exists()) return response()->json(['message'=>'Cannot delete a category linked to raw materials.'],422); $category->delete(); return response()->noContent();}
 public function materials(Request $r){$q=RawMaterial::with('category')->when($r->search,fn($q,$v)=>$q->where(fn($x)=>$x->where('name','like',"%$v%")->orWhere('code','like',"%$v%"))); return response()->json(['data'=>$q->latest()->paginate($r->integer('per_page',20))]);}
 public function materialStore(Request $r){$data=$r->validate(['name'=>'required|string|max:255','code'=>'required|string|max:40','category_id'=>'nullable|exists:recipe_material_categories,id','description'=>'nullable|string','package_size'=>'required|numeric|min:0.000001','package_unit'=>'required|in:L,ML,KG,G','package_cost'=>'required|numeric|min:0','base_unit'=>'required|in:L,ML,KG,G','available_quantity'=>'nullable|numeric|min:0','barcode'=>'nullable|string','minimum_stock_alert'=>'nullable|numeric|min:0','active'=>'boolean']); return response()->json(['data'=>RawMaterial::create($this->service->recalculateMaterial($data))],201);}
 public function materialUpdate(Request $r,RawMaterial $material){$data=$r->validate(['name'=>'required|string|max:255','code'=>'required|string|max:40','category_id'=>'nullable|exists:recipe_material_categories,id','description'=>'nullable|string','package_size'=>'required|numeric|min:0.000001','package_unit'=>'required|in:L,ML,KG,G','package_cost'=>'required|numeric|min:0','base_unit'=>'required|in:L,ML,KG,G','available_quantity'=>'nullable|numeric|min:0','barcode'=>'nullable|string','minimum_stock_alert'=>'nullable|numeric|min:0','active'=>'boolean']); $material->update($this->service->recalculateMaterial($data)); return response()->json(['data'=>$material->fresh('category')]);}
 public function materialDestroy(RawMaterial $material){$material->delete(); return response()->noContent();}
 public function products(Request $r){return response()->json(['data'=>Product::query()->select('id','name','sku','stock')->when($r->search,fn($q,$v)=>$q->where('name','like',"%$v%"))->limit(100)->get()]);}
 public function recipes(Request $r){$q=Recipe::with(['product','items.material'])->when($r->search,fn($q,$v)=>$q->where('code','like',"%$v%")); return response()->json(['data'=>$q->latest()->paginate($r->integer('per_page',20))]);}
 public function recipeStore(Request $r){$data=$r->validate(['product_id'=>'required|exists:products,id','package_size'=>'nullable|string','package_unit'=>'nullable|string|max:8','description'=>'nullable|string','status'=>'nullable|in:active,inactive','items'=>'required|array|min:1','items.*.material_id'=>'required|exists:recipe_materials,id','items.*.required_quantity'=>'required|numeric|min:0.000001','items.*.waste_quantity'=>'nullable|numeric|min:0','items.*.unit'=>'required|in:L,ML,KG,G']); return response()->json(['data'=>$this->service->saveRecipe($data)],201);}
 public function recipeUpdate(Request $r,Recipe $recipe){$data=$r->validate(['product_id'=>'required|exists:products,id','package_size'=>'nullable|string','package_unit'=>'nullable|string|max:8','description'=>'nullable|string','status'=>'nullable|in:active,inactive','items'=>'required|array|min:1','items.*.material_id'=>'required|exists:recipe_materials,id','items.*.required_quantity'=>'required|numeric|min:0.000001','items.*.waste_quantity'=>'nullable|numeric|min:0','items.*.unit'=>'required|in:L,ML,KG,G']); return response()->json(['data'=>$this->service->saveRecipe($data,$recipe)],200);}
 public function recipeDestroy(Recipe $recipe){$recipe->delete(); return response()->noContent();}
 public function orders(Request $r){$q=ProductionOrder::with(['product','recipe'])->when($r->status,fn($q,$v)=>$q->where('status',$v)); return response()->json(['data'=>$q->latest()->paginate($r->integer('per_page',20))]);}
 public function orderStore(Request $r){$data=$r->validate(['recipe_id'=>'required|exists:product_recipes,id','planned_quantity'=>'required|numeric|min:0.000001','notes'=>'nullable|string']); $recipe=Recipe::findOrFail($data['recipe_id']); $order=ProductionOrder::create(['recipe_id'=>$recipe->id,'product_id'=>$recipe->product_id,'order_number'=>'PRO-'.now()->format('YmdHis').'-'.random_int(100,999),'planned_quantity'=>$data['planned_quantity'],'expected_cost'=>round((float)$recipe->total_cost*(float)$data['planned_quantity'],6),'notes'=>$data['notes']??null]); return response()->json(['data'=>$order->load(['recipe.product'])],201);}
 public function orderShow(ProductionOrder $order){return response()->json(['data'=>$order->load(['product','recipe.items.material','items.material'])]);}
 public function confirm(ProductionOrder $order){return response()->json(['data'=>$this->service->confirm($order)]);}
 public function report(Request $r){$q=ProductionOrder::query()->when($r->from,fn($q,$v)=>$q->whereDate('created_at','>=',$v))->when($r->to,fn($q,$v)=>$q->whereDate('created_at','<=',$v))->when($r->product_id,fn($q,$v)=>$q->where('product_id',$v)); return response()->json(['data'=>['orders'=>$q->with('product')->latest()->get(),'summary'=>['total_cost'=>(clone $q)->sum('actual_cost'),'produced_quantity'=>(clone $q)->sum('produced_quantity'),'waste'=>(clone $q)->sum('actual_waste')]]]);}
}
